#!/usr/bin/env bash
#
# Build a versioned .deb from the plugin install tree.
#
# Inputs (environment):
#   INSTALL_DIR     - cmake --install destination (required)
#   META_FILE       - plugin-meta.txt generated by CMake (required)
#   OUTPUT_DIR      - where to write the .deb (default: dist)
#   OBS_MIN_VERSION - minimum obs-studio version for Depends (default: 31.0.0)
#   PACKAGE_REVISION - debian revision suffix (default: 1)

set -euo pipefail

: "${INSTALL_DIR:?INSTALL_DIR is required}"
: "${META_FILE:?META_FILE is required}"

OUTPUT_DIR="${OUTPUT_DIR:-dist}"
OBS_MIN_VERSION="${OBS_MIN_VERSION:-31.0.0}"
PACKAGE_REVISION="${PACKAGE_REVISION:-1}"
mkdir -p "${OUTPUT_DIR}"

# shellcheck disable=SC1090
source "${META_FILE}"

DEB_ARCH="$(dpkg-architecture -q DEB_HOST_ARCH)"
PACKAGE_NAME="obs-plugin-${PLUGIN_TARGET}"
PACKAGE_VERSION="${PLUGIN_VERSION}-${PACKAGE_REVISION}"
PKG_ROOT="$(mktemp -d)"
trap 'rm -rf "${PKG_ROOT}"' EXIT

# 1. File tree: dpkg-deb wants DEBIAN/ plus the real filesystem layout.
cp -a "${INSTALL_DIR}/." "${PKG_ROOT}/"
mkdir -p "${PKG_ROOT}/DEBIAN"

INSTALLED_SIZE="$(du -sk --exclude=DEBIAN "${PKG_ROOT}" | cut -f1)"

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
sed \
  -e "s/@PACKAGE_NAME@/${PACKAGE_NAME}/g" \
  -e "s/@PACKAGE_VERSION@/${PACKAGE_VERSION}/g" \
  -e "s/@DEB_ARCH@/${DEB_ARCH}/g" \
  -e "s/@PLUGIN_NAME@/${PLUGIN_NAME}/g" \
  -e "s/@INSTALLED_SIZE@/${INSTALLED_SIZE}/g" \
  -e "s/@OBS_MIN_VERSION@/${OBS_MIN_VERSION}/g" \
  "${SCRIPT_DIR}/../packaging/deb/control.in" > "${PKG_ROOT}/DEBIAN/control"

install -m 0755 "${SCRIPT_DIR}/../packaging/deb/postinst" "${PKG_ROOT}/DEBIAN/postinst"

# 2. Resolve shared-library dependencies against the plugin .so.
PLUGIN_SO="$(find "${PKG_ROOT}" -name "${PLUGIN_FILE}" -type f -print -quit)"
if [ -z "${PLUGIN_SO}" ]; then
	echo "error: ${PLUGIN_FILE} not found under ${PKG_ROOT}" >&2
	exit 1
fi

# Prefer dpkg-shlibdeps when the linked libraries are registered dpkg
# packages. When libobs comes from a custom prefix (e.g. /opt/obs in the
# Docker builder) it has no shlibs metadata, so fall back to ldd and map each
# resolved shared object back to its owning package with dpkg -S.
DPKG_WORK="$(mktemp -d)"
mkdir -p "${DPKG_WORK}/debian"
printf 'Source: %s\nPackage: %s\nArchitecture: %s\nDescription: temp\n stub\n' \
	"${PACKAGE_NAME}" "${PACKAGE_NAME}" "${DEB_ARCH}" > "${DPKG_WORK}/debian/control"
SHLIBS="$(
	cd "${DPKG_WORK}"
	dpkg-shlibdeps -O --ignore-missing-info "${PLUGIN_SO}" 2>/dev/null \
		| sed 's/^shlibs:Depends=//' || true
)"

if [ -z "${SHLIBS}" ]; then
	echo "note: dpkg-shlibdeps unavailable, deriving dependencies from ldd" >&2
	PKG_SET="$(mktemp)"
	for lib in $(ldd "${PLUGIN_SO}" | awk '{print $3}' | grep '^/'); do
		pkg="$(dpkg -S "${lib}" 2>/dev/null | cut -d: -f1 | head -1 || true)"
		[ -n "${pkg}" ] && echo "${pkg}" >> "${PKG_SET}"
	done
	SHLIBS="$(sort -u "${PKG_SET}" | paste -sd, - || true)"
fi
rm -rf "${DPKG_WORK}"
if [ -n "${SHLIBS}" ]; then
	# Escape & and the sed delimiter in package names/version constraints.
	ESCAPED="$(printf '%s' "${SHLIBS}" | sed -e 's/[&/]/\\&/g')"
	sed -i "s/\${shlibs:Depends}/${ESCAPED}/" "${PKG_ROOT}/DEBIAN/control"
else
	sed -i 's/, \${shlibs:Depends}//' "${PKG_ROOT}/DEBIAN/control"
fi

if grep -q '${shlibs:Depends}' "${PKG_ROOT}/DEBIAN/control"; then
	echo "error: shlibs dependency substitution failed" >&2
	cat "${PKG_ROOT}/DEBIAN/control" >&2
	exit 1
fi

# 3. Lint the tree and build the package.
dpkg-deb --root-owner-group --build "${PKG_ROOT}" \
	"${OUTPUT_DIR}/${PACKAGE_NAME}_${PACKAGE_VERSION}_${DEB_ARCH}.deb"

dpkg-deb --info "${OUTPUT_DIR}/${PACKAGE_NAME}_${PACKAGE_VERSION}_${DEB_ARCH}.deb"
echo "Created ${OUTPUT_DIR}/${PACKAGE_NAME}_${PACKAGE_VERSION}_${DEB_ARCH}.deb"
